import React, { useState, useEffect } from 'react';
import { ethers } from 'ethers';
import detectEthereumProvider from '@metamask/detect-provider';

function WalletConnect({ onWalletConnected }) {
  // ===== STATE MANAGEMENT =====
  const [account, setAccount] = useState(null);
  const [balance, setBalance] = useState(null);
  const [network, setNetwork] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [provider, setProvider] = useState(null);
  const [isMetaMaskInstalled, setIsMetaMaskInstalled] = useState(false);

  // ===== KIỂM TRA METAMASK KHI LOAD TRANG =====
  useEffect(() => {
    checkMetaMaskInstalled();
    checkPreviousConnection();
  }, []);

  // ===== KIỂM TRA METAMASK ĐÃ CÀI ĐẶT CHƯA =====
  const checkMetaMaskInstalled = async () => {
    const provider = await detectEthereumProvider();
    setIsMetaMaskInstalled(!!provider);
    
    if (provider) {
      setProvider(new ethers.providers.Web3Provider(provider));
    }
  };

  // ===== KIỂM TRA KẾT NỐI TRƯỚC ĐÓ =====
  const checkPreviousConnection = async () => {
    if (window.ethereum) {
      try {
        const accounts = await window.ethereum.request({ 
          method: 'eth_accounts' 
        });
        
        if (accounts.length > 0) {
          await handleAccountChanged(accounts[0]);
        }
      } catch (error) {
        console.error("Lỗi kiểm tra kết nối cũ:", error);
      }
    }
  };

  // ===== XỬ LÝ KHI TÀI KHOẢN THAY ĐỔI =====
  const handleAccountChanged = async (newAccount) => {
    if (!newAccount) {
      // Người dùng ngắt kết nối
      setAccount(null);
      setBalance(null);
      setNetwork(null);
      if (onWalletConnected) onWalletConnected(null);
      return;
    }

    setAccount(newAccount);
    
    // Lấy số dư
    if (provider) {
      const balance = await provider.getBalance(newAccount);
      setBalance(ethers.utils.formatEther(balance));
      
      // Lấy thông tin network
      const network = await provider.getNetwork();
      setNetwork(network);
      
      // Gọi callback để component cha biết đã kết nối
      if (onWalletConnected) {
        onWalletConnected({
          account: newAccount,
          balance: ethers.utils.formatEther(balance),
          chainId: network.chainId
        });
      }
    }
  };

  // ===== KẾT NỐI VÍ METAMASK =====
  const connectWallet = async () => {
    setError('');
    setLoading(true);

    try {
      // Kiểm tra MetaMask đã được cài đặt chưa
      if (!window.ethereum) {
        throw new Error("MetaMask chưa được cài đặt!");
      }

      // Yêu cầu quyền truy cập tài khoản
      const accounts = await window.ethereum.request({
        method: 'eth_requestAccounts'
      });

      if (accounts.length === 0) {
        throw new Error("Không tìm thấy tài khoản nào");
      }

      // Xử lý tài khoản mới
      await handleAccountChanged(accounts[0]);

      // Lắng nghe sự kiện thay đổi tài khoản
      window.ethereum.on('accountsChanged', handleAccountChanged);

      // Lắng nghe sự kiện thay đổi mạng
      window.ethereum.on('chainChanged', () => {
        window.location.reload();
      });

    } catch (error) {
      console.error("Lỗi kết nối:", error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  // ===== NGẮT KẾT NỐI =====
  const disconnectWallet = () => {
    setAccount(null);
    setBalance(null);
    setNetwork(null);
    if (onWalletConnected) onWalletConnected(null);
  };

  // ===== CHUYỂN ĐỔI MẠNG =====
  const switchNetwork = async (targetChainId) => {
    if (!window.ethereum) return;

    try {
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: ethers.utils.hexValue(targetChainId) }],
      });
    } catch (error) {
      console.error("Lỗi chuyển mạng:", error);
      setError("Không thể chuyển mạng");
    }
  };

  // ===== RÚT GỌN ĐỊA CHỈ VÍ =====
  const shortenAddress = (address) => {
    if (!address) return '';
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  };

  // ===== LẤY TÊN MẠNG =====
  const getNetworkName = (chainId) => {
    if (!chainId) return 'Unknown';
    
    const networks = {
      1: 'Ethereum Mainnet',
      3: 'Ropsten',
      4: 'Rinkeby',
      5: 'Goerli',
      42: 'Kovan',
      56: 'BSC',
      97: 'BSC Testnet',
      137: 'Polygon',
      80001: 'Mumbai',
      11155111: 'Sepolia',
      1337: 'Local Hardhat',
      31337: 'Local Hardhat'
    };
    
    return networks[chainId] || `Chain ID: ${chainId}`;
  };

  // ===== GIAO DIỆN =====
  return (
    <div className="wallet-connect-container">
      {/* Header với tiêu đề */}
      <div className="wallet-header">
        <h2>🔌 Kết nối ví MetaMask</h2>
        {!isMetaMaskInstalled && (
          <div className="warning-badge">
            ⚠️ Chưa cài MetaMask
          </div>
        )}
      </div>

      {/* Nội dung chính */}
      <div className="wallet-content">
        {!account ? (
          // TRƯỜNG HỢP CHƯA KẾT NỐI
          <div className="connect-section">
            <div className="wallet-icon">🦊</div>
            <h3>Kết nối với MetaMask</h3>
            <p className="connect-description">
              Kết nối ví MetaMask của bạn để bắt đầu tham gia đấu giá
            </p>
            
            {!isMetaMaskInstalled && (
              <div className="install-metamask">
                <p>Bạn chưa cài đặt MetaMask?</p>
                <a 
                  href="https://metamask.io/download/" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="install-link"
                >
                  📥 Tải MetaMask ngay
                </a>
              </div>
            )}
            
            <button 
              onClick={connectWallet}
              disabled={loading || !isMetaMaskInstalled}
              className={`connect-btn ${loading ? 'loading' : ''}`}
            >
              {loading ? (
                <>
                  <span className="spinner">⏳</span>
                  Đang kết nối...
                </>
              ) : (
                <>
                  <span>🦊</span>
                  Kết nối MetaMask
                </>
              )}
            </button>
            
            {error && (
              <div className="error-message">
                ❌ {error}
              </div>
            )}
          </div>
        ) : (
          // TRƯỜNG HỢP ĐÃ KẾT NỐI
          <div className="wallet-info">
            {/* Thông tin tài khoản */}
            <div className="info-card">
              <div className="info-icon">👤</div>
              <div className="info-content">
                <span className="info-label">Tài khoản</span>
                <span className="info-value address" title={account}>
                  {shortenAddress(account)}
                </span>
                <button 
                  className="copy-btn"
                  onClick={() => navigator.clipboard.writeText(account)}
                  title="Copy địa chỉ"
                >
                  📋
                </button>
              </div>
            </div>

            {/* Thông tin số dư */}
            <div className="info-card">
              <div className="info-icon">💰</div>
              <div className="info-content">
                <span className="info-label">Số dư</span>
                <span className="info-value balance">
                  {parseFloat(balance).toFixed(4)} ETH
                </span>
              </div>
            </div>

            {/* Thông tin mạng */}
            <div className="info-card">
              <div className="info-icon">🌐</div>
              <div className="info-content">
                <span className="info-label">Mạng</span>
                <span className="info-value network">
                  {getNetworkName(network?.chainId)}
                </span>
                <select 
                  className="network-select"
                  onChange={(e) => switchNetwork(parseInt(e.target.value))}
                  value={network?.chainId || ''}
                >
                  <option value="1">Ethereum Mainnet</option>
                  <option value="11155111">Sepolia Testnet</option>
                  <option value="97">BSC Testnet</option>
                  <option value="1337">Local Hardhat</option>
                </select>
              </div>
            </div>

            {/* Trạng thái kết nối */}
            <div className="connection-status">
              <div className="status-dot connected"></div>
              <span>Đã kết nối</span>
            </div>

            {/* Nút ngắt kết nối */}
            <button 
              onClick={disconnectWallet}
              className="disconnect-btn"
            >
              🔌 Ngắt kết nối
            </button>
          </div>
        )}
      </div>

      {/* Hướng dẫn sử dụng */}
      {!account && (
        <div className="guide-section">
          <h4>📚 Hướng dẫn nhanh:</h4>
          <ol>
            <li>Cài đặt MetaMask (nếu chưa có)</li>
            <li>Tạo ví hoặc import ví cũ</li>
            <li>Chuyển sang mạng Sepolia Testnet</li>
            <li>Nhận ETH test từ faucet</li>
            <li>Nhấn nút "Kết nối MetaMask"</li>
          </ol>
          <div className="faucet-links">
            <p>🔗 Faucet nhận ETH test:</p>
            <a href="https://sepoliafaucet.com/" target="_blank" rel="noopener noreferrer">
              Sepolia Faucet (Infura)
            </a>
            <a href="https://faucet.quicknode.com/ethereum/sepolia" target="_blank" rel="noopener noreferrer">
              QuickNode Faucet
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

export default WalletConnect;
